with exploded as (select id, plan, effective_from, currency, explode(tier_limits) as element from price_tiers) select *, dense_rank() over w_grp as element_dense_rank, rank() over w_grp_2 as element_rank, cume_dist() over w_grp_3 as element_cume_dist from exploded window w_grp as (order by element desc nulls last), w_grp_2 as (partition by currency, plan order by element nulls first), w_grp_3 as (partition by currency order by element nulls last)
